export interface PersonWithClaims {
  id: number;
  /** The version the person was last saved at; an edit sends the one its editor loaded. */
  version: number;
  name: string;
  grade: string;
  claims: Claim[];
  /** The amounts of the OPEN, PENDING and SETTLED claims added up; only the SETTLED ones while on hold. */
  claimed: string;
  /** Claimed at the rate for the person's grade; null when the grade has no rate. */
  dueTotal: string | null;
  /** How many statements were taken for the person. */
  statementCount: number;
  /** The last statement's due-total; null when there is none or it was n/a. */
  statedTotal: string | null;
  /** The sheet's today when the last statement was taken; null when there is none. */
  statementDate: string | null;
  /** Whether a retirement date is set: retired at once, whatever the date. */
  retired: boolean;
  /** The date the person is retired from; no claim dated after it can be added. Null when not retired. */
  retiredFrom: string | null;
  /** Whether the person is on hold: their OPEN and PENDING claims then count in no live total. */
  held: boolean;
  /** How many of the claims that count are overdue. */
  overdueCount: number;
  /** The due figures of the overdue claims that count, added up. */
  overdueTotal: string;
  /** The ids of the people on the sheet the person named as their patrons. */
  patrons: number[];
}

const AMOUNT = /^-?\d{1,12}(\.\d{1,2})?$/;
const NUMBER = /^([1-9]\d{0,8}|.{1,100}-[1-9]\d{0,8})$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;
/** Cents in an amount shown with two decimals ("12.50" is 1250). */
function cents(amount: string): number {
  return Math.round(Number(amount) * 100);
}

/** Per period id, the dues of the claims that count whose date falls in it, added up, or once closed the
 * due-total fixed then; the OPEN and PENDING claims of a person on hold count in none. */
export function periodDueTotals(periods: Period[], people: PersonWithClaims[]): Record<number, string> {
  const totals: Record<number, number> = {};
  for (const p of periods) totals[p.id] = 0;
  const closed = new Map(periods.filter((p) => p.closed).map((p) => [p.id, p.closedTotal ?? '0.00']));
  for (const person of people) {
    for (const c of person.claims) {
      const unpaid = c.status === 'OPEN' || c.status === 'PENDING';
      if ((!unpaid && c.status !== 'SETTLED') || c.due === null) continue;
      if (person.held && unpaid) continue;
      const period = periodOf(periods, c.date);
      if (period && !closed.has(period.id)) totals[period.id] += cents(c.due);
    }
  }
  const shown: Record<number, string> = {};
  for (const id of Object.keys(totals)) shown[+id] = closed.get(+id) ?? (totals[+id] / 100).toFixed(2);
  return shown;
}

